1	#!/usr/bin/env node
2	// Minimal stdio MCP probe: exposes one tool that returns process.cwd().
3	
4	process.stdin.setEncoding('utf8');
5	
6	let buffer = '';
7	
8	function send(id, result) {
9	  const payload = JSON.stringify({ jsonrpc: '2.0', id, result });
10	  process.stdout.write(`Content-Length: ${Buffer.byteLength(payload)}\r\n\r\n${payload}`);
11	}
12	
13	function sendError(id, code, message) {
14	  const payload = JSON.stringify({ jsonrpc: '2.0', id, error: { code, message } });
15	  process.stdout.write(`Content-Length: ${Buffer.byteLength(payload)}\r\n\r\n${payload}`);
16	}
17	
18	process.stdin.on('data', (chunk) => {
19	  buffer += chunk;
20	  while (true) {
21	    const headerEnd = buffer.indexOf('\r\n\r\n');
22	    if (headerEnd === -1) return;
23	    const headers = buffer.slice(0, headerEnd);
24	    const match = headers.match(/Content-Length:\s*(\d+)/i);
25	    if (!match) {
26	      buffer = buffer.slice(headerEnd + 4);
27	      continue;
28	    }
29	    const length = parseInt(match[1], 10);
30	    const bodyStart = headerEnd + 4;
31	    if (buffer.length < bodyStart + length) return;
32	    const body = buffer.slice(bodyStart, bodyStart + length);
33	    buffer = buffer.slice(bodyStart + length);
34	    let request;
35	    try {
36	      request = JSON.parse(body);
37	    } catch {
38	      sendError(null, -32700, 'Parse error');
39	      continue;
40	    }
41	    const { id, method, params } = request;
42	    if (method === 'initialize') {
43	      send(id, {
44	        protocolVersion: '2024-11-05',
45	        capabilities: {},
46	        serverInfo: { name: 'probe-cwd', version: '0.0.1' }
47	      });
48	    } else if (method === 'initialized') {
49	      // notification, no response
50	    } else if (method === 'tools/list') {
51	      send(id, {
52	        tools: [
53	          {
54	            name: 'get_cwd',
55	            description: 'Return the current working directory of the stdio MCP server process.',
56	            inputSchema: { type: 'object', properties: {}, required: [] }
57	          }
58	        ]
59	      });
60	    } else if (method === 'tools/call') {
61	      const name = params?.name;
62	      if (name === 'get_cwd') {
63	        send(id, {
64	          content: [{ type: 'text', text: JSON.stringify({ cwd: process.cwd() }) }],
65	          isError: false
66	        });
67	      } else {
68	        sendError(id, -32601, `Unknown tool: ${name}`);
69	      }
70	    } else if (id !== undefined) {
71	      sendError(id, -32601, `Method not found: ${method}`);
72	    }
73	  }
74	});
